  let lastX = 0;
  let lastY = 0;
  let memeIndex = 0;
  const DISTANCE_THRESHOLD = 52;
  const prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  if (prefersReducedMotion) return;

  function createPolaroid(x, y, customRot = null) {
    const card = document.createElement('div');
    card.className = 'u323-p';
    card.style.left = `${x}px`;
    card.style.top = `${y}px`;

    const rot = customRot !== null ? customRot : ((Math.random() * 34) - 17);
    card.style.setProperty('--rot', `${rot}deg`);

    const delayMs = 900 + Math.floor(Math.random() * 450);
    card.style.setProperty('--out-delay', `${delayMs}ms`);

    const img = document.createElement('img');
    img.src = memeImages[memeIndex % memeImages.length];
    memeIndex++;
    card.appendChild(img);

    container.appendChild(card);

    setTimeout(() => {
      if (card.parentNode === container) {
        container.removeChild(card);
      }
    }, delayMs + 380);
  }

  function handleMove(e) {
    const rect = stage.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;

    const x = clientX - rect.left;
    const y = clientY - rect.top;

    if (x < 0 || x > rect.width || y < 0 || y > rect.height) return;

    const dx = x - lastX;
    const dy = y - lastY;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist >= DISTANCE_THRESHOLD) {
      lastX = x;
      lastY = y;
      createPolaroid(x, y);
    }
  }

  function handleBurst(e) {
    const rect = stage.getBoundingClientRect();
    const clientX = e.clientX || (e.touches && e.touches[0].clientX) || (rect.left + rect.width / 2);
    const clientY = e.clientY || (e.touches && e.touches[0].clientY) || (rect.top + rect.height / 2);

    const cx = clientX - rect.left;
    const cy = clientY - rect.top;

    // 5-photo burst in fan pattern
    const offsets = [
      { dx: -45, dy: -30, rot: -22 },
      { dx: -20, dy: -55, rot: -10 },
      { dx: 0,   dy: -40, rot: 0 },
      { dx: 22,  dy: -55, rot: 12 },
      { dx: 45,  dy: -25, rot: 24 }
    ];

    offsets.forEach((cfg, i) => {
      setTimeout(() => {
        createPolaroid(cx + cfg.dx, cy + cfg.dy, cfg.rot);
      }, i * 35);
    });
  }

  stage.addEventListener('mousemove', handleMove, { passive: true });
  stage.addEventListener('touchmove', handleMove, { passive: true });
  stage.addEventListener('click', handleBurst);

  // Initial subtle ambient drop
  setTimeout(() => {
    const rect = stage.getBoundingClientRect();
    if (rect.width > 0) {
      createPolaroid(rect.width * 0.35, rect.height * 0.3, -12);
      setTimeout(() => createPolaroid(rect.width * 0.65, rect.height * 0.45, 14), 220);
    }
  }, 600);
})();
